const KEYWORD_MAP = {
  'automation-heavy': ['n8n','zapier','make.com','rpa','workflow','ci/cd','cicd','webhook','automation'],
  'web-dev':          ['react','vue','angular','svelte','html','css','tailwind','next.js','nextjs','frontend'],
  'data':             ['sql','python','pandas','numpy','machine learning','deep learning','analytics','etl','data science','tensorflow','pytorch'],
  'devops':           ['docker','kubernetes','k8s','aws','gcp','azure','linux','terraform','ansible','helm','cloud'],
};
const BACKEND_KW = ['node','node.js','django','fastapi','flask','express','spring','laravel','rails','backend','graphql','rest api'];
return $input.all().map((item) => {
  const c = item.json || {};
  let arr = [];
  if (Array.isArray(c.skills))           arr = c.skills;
  else if (typeof c.skills === 'string') arr = c.skills.split(/[,;|/]/);
  arr = arr.map((s) => String(s).trim().toLowerCase()).filter(Boolean);
  const text = arr.join(', ');
  const scores = {};
  for (const [cat, kws] of Object.entries(KEYWORD_MAP)) {
    scores[cat] = kws.filter((k) => text.includes(k)).length;
  }
  let best = 'other', bestScore = 0;
  for (const [cat, sc] of Object.entries(scores)) {
    if (sc > bestScore) { bestScore = sc; best = cat; }
  }
  const hasWeb     = scores['web-dev'] > 0;
  const hasBackend = scores['data'] > 0 || BACKEND_KW.some((k) => text.includes(k));
  const keywordCategory = (hasWeb && hasBackend) ? 'fullstack' : best;
  const total = Object.values(scores).reduce((a, b) => a + b, 0);
  const keywordConfidence = total === 0 ? 0 : Number(Math.min(1, bestScore / total).toFixed(2));
  return { json: { ...c, skills_normalized: text, skills_array: arr, keywordCategory, keywordConfidence } };
});

const store = $getWorkflowStaticData('global');
store.primaryResults = [];
store.retryResults   = [];
return $input.all();

const threshold = Number($('Run Config').first().json.needsReviewThreshold ?? 0.6);
const src    = $('Loop — Primary').item.json;
const llmOut = $input.first().json;
const id     = src.id ?? llmOut.id;
const parsed = llmOut.output;
const failed = !!llmOut.error || !parsed?.skill_category;
if (failed) {
  return [{ json: {
    id, tagged: false,
    skills_normalized: src.skills_normalized ?? null,
    keywordCategory:   src.keywordCategory   ?? 'other',
    keywordConfidence: src.keywordConfidence ?? 0,
    keyword_hint:      src.keywordCategory   ?? null,
    error: llmOut.error ? (llmOut.error.message ?? String(llmOut.error)) : 'no structured output',
  }}];
}
const confidence   = Number(Number(parsed.confidence ?? 0).toFixed(2));
const needs_review = confidence < threshold;
return [{ json: {
  id, tagged: true,
  skill_category: parsed.skill_category, confidence,
  reasoning:      parsed.reasoning ?? '',
  source:         'llm', needs_review,
  keyword_hint:      src.keywordCategory   ?? null,
  skills_normalized: src.skills_normalized ?? null,
  error: null,
}}];

